int main() {
    /* 初始化空 AVL 树 */
    AVLTree *tree = (AVLTree *)newAVLTree();
    /* 插入节点 */
    // 请关注插入节点后，AVL 树是如何保持平衡的
    testInsert(tree, 1);
    testInsert(tree, 2);
