    /* 插入重复节点 */
    testInsert(tree, 7);

    /* 删除节点 */
    // 请关注删除节点后，AVL 树是如何保持平衡的
    testRemove(tree, 8); // 删除度为 0 的节点
    testRemove(tree, 5); // 删除度为 1 的节点
    testRemove(tree, 4); // 删除度为 2 的节点

    /* 查询节点 */
    TreeNode *node = search(tree, 7);
    printf("\n查找到的节点对象节点值 = %d \n", node->val);

    // 释放内存
    delAVLTree(tree);
