                let temp = node.right;
                while (temp.left !== null) {
                    temp = temp.left;
                }
                node.right = this.removeHelper(node.right, temp.val);
                node.val = temp.val;
            }
        }
        this.updateHeight(node); // 更新节点高度
        /* 2. 执行旋转操作，使该子树重新恢复平衡 */
        node = this.rotate(node);
        // 返回子树的根节点
        return node;
    }

    /* 查找节点 */
    search(val: number): TreeNode {
        let cur = this.root;
        // 循环查找，越过叶节点后跳出
        while (cur !== null) {
            if (cur.val < val) {
                // 目标节点在 cur 的右子树中
